/* OM DNA — Mediterranean white, ciel blue air, the gold star */
.theme-marseille {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.981 0.008 228.9);
  --surface-2: oklch(0.960 0.016 233.0);
  --fg: oklch(0.284 0.034 250.8);
  --fg-muted: oklch(0.638 0.035 246.9);
  --accent: oklch(0.706 0.128 229.9);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.767 0.139 91.1);
  --line: oklch(0.932 0.026 231.6);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.706 0.128 229.9);
  --radius: 0.75rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Teko", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-marseille h1,
.theme-marseille h2,
.theme-marseille h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-marseille { --font-ui: var(--font-display); }
.theme-marseille h1, .theme-marseille h2 { text-transform: uppercase; }
.theme-marseille button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-marseille h2::before { content: "★ "; color: var(--accent-2); }
.theme-marseille h1 { font-weight: 600; }
.theme-marseille button { font-weight: 600; }


/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
